{
  "moneyMethods": [
    "deposit: payable entry point; requires deposits_paused == false and non-zero attached deposit; credits env::attached_deposit() to the caller's recorded balance via saturating_add; the actual NEAR stays on the contract account",
    "withdraw: debits the caller's recorded balance (require balance >= amount, then saturating_sub) and Promise::transfer(amount) sends NEAR out to an arbitrary receiver_id chosen by the caller, which need not be the caller",
    "set_deposits_paused: moves no NEAR; owner-only flag that blocks or unblocks deposit()",
    "balance_of: view only; returns the recorded balance (or 0); moves nothing",
    "deposits_paused / owner: view only; move nothing"
  ],
  "balanceStorage": [
    "balances: LookupMap<AccountId, NearToken> under storage prefix b\"b\"; per-account recorded NEAR credited by deposit() and debited by withdraw() — the real NEAR sits as the contract account's own balance backing these IOUs",
    "owner: AccountId stored at init; the authority compared in set_deposits_paused; no method exists to change it after init",
    "deposits_paused: bool flag; when true, deposit() panics; set only by owner"
  ],
  "privilegedMethods": [
    {
      "method": "set_deposits_paused",
      "whoMayCall": "only the stored owner (env::predecessor_account_id() == self.owner)"
    },
    {
      "method": "new",
      "whoMayCall": "anyone, but only before first initialization; the near-sdk #[init] macro panics if contract state already exists, so re-init is blocked at source level"
    }
